  "translation": "仲弓问仁。孔子说：“出门如同会见贵宾一样恭敬，役使民众如同承办大祭一样郑重。自己不愿承受的，不要施加给别人。在邦国任事不招怨，在卿大夫之家任事也不招怨。”仲弓说：“我虽然不聪敏，愿意照这些话去做。”",
  "insight": "仲弓问仁，孔子从接人、使民的恭敬说到己所不欲勿施于人，以及在邦、在家的无怨。“家”在此主要指卿大夫之家，不只是现代家庭。现代借鉴是郑重待人，不把自己不愿承受的事强加给别人；换位思考仍需询问实际意愿，不能把自己的偏好替他人作主，也不能保证如此便无人怨恨。"
